DO $coding_artifacts$ BEGIN IF to_regclass('public.platform_workspaces') IS NULL OR to_regclass('public.platform_agent_runs') IS NULL THEN RETURN; END IF;
CREATE TABLE platform_artifacts(id UUID PRIMARY KEY,tenant_id VARCHAR(36) NOT NULL,project_id UUID NOT NULL,task_id UUID NOT NULL,agent_run_id VARCHAR(36) NOT NULL,workspace_id UUID NOT NULL,artifact_type VARCHAR(32) NOT NULL,name VARCHAR(200) NOT NULL,content_ref TEXT,content_hash VARCHAR(80) NOT NULL,summary TEXT,metadata_json JSONB NOT NULL DEFAULT '{}'::JSONB,created_at TIMESTAMPTZ NOT NULL,
CONSTRAINT ck_platform_artifact_type CHECK(artifact_type IN('PATCH','COMMIT_PROPOSAL','TEST_REPORT','ACCEPTANCE_EVIDENCE')),CONSTRAINT fk_platform_artifact_workspace FOREIGN KEY(workspace_id,project_id,tenant_id) REFERENCES platform_workspaces(id,project_id,tenant_id),CONSTRAINT fk_platform_artifact_task FOREIGN KEY(project_id,task_id) REFERENCES platform_tasks(project_id,id),CONSTRAINT fk_platform_artifact_run FOREIGN KEY(agent_run_id) REFERENCES platform_agent_runs(id));
CREATE INDEX idx_platform_artifact_run ON platform_artifacts(agent_run_id,created_at);CREATE INDEX idx_platform_artifact_task ON platform_artifacts(task_id,created_at);
END $coding_artifacts$;
